INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist das Definieren von Arbeitspaketen Teil der Planung?', 2, '[{"text": "Ja", "correct": true, "because": "Strukturiert Aufgaben"}, {"text": "Nein", "correct": false, "because": "Es gehört zur Planung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel hat das Definieren von Arbeitspaketen?', 3, '[{"text": "Projekt in überschaubare Einheiten teilen", "correct": true, "because": "Fördert Kontrolle"}, {"text": "Kosten sofort senken", "correct": false, "because": "Kein primäres Ziel"}, {"text": "Teamgröße festlegen", "correct": false, "because": "Späterer Schritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Arbeitspakete erleichtern die Zuordnung. b) Sie werden erst in der Durchführung definiert.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Planung ist entscheidend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zur Definition von Arbeitspaketen?', 4, '[{"text": "Beschreibung der Aufgabe", "correct": true, "because": "Definiert Inhalt"}, {"text": "Unklare Ziele", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "Verantwortlicher", "correct": true, "because": "Weist Zuständigkeit zu"}, {"text": "Zeitrahmen", "correct": true, "because": "Setzt Dauer"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Projekt ohne definierte Arbeitspakete geplant werden?', 2, '[{"text": "Nein", "correct": true, "because": "Fehlt Struktur"}, {"text": "Ja", "correct": false, "because": "Risiko von Chaos"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Arbeitspaket ist schlecht definiert?', 3, '[{"text": "Irgendwas machen", "correct": true, "because": "Zu vage"}, {"text": "Datenbank bis 15. Mai optimieren", "correct": false, "because": "Klar und spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist das Definieren von Arbeitspaketen nur für große Projekte nötig?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Projekte profitieren"}, {"text": "Ja", "correct": false, "because": "Breite Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode unterstützt das Definieren von Arbeitspaketen?', 3, '[{"text": "Projektstrukturplan (PSP)", "correct": true, "because": "Teilt Projekt hierarchisch"}, {"text": "Keine Struktur", "correct": false, "because": "Fehlt Systematik"}, {"text": "Zufällige Liste", "correct": false, "because": "Unübersichtlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Arbeitspakete haben klare Ergebnisse. b) Sie sind immer teamübergreifend.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist flexibel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielen Arbeitspakete in der Planung?', 3, '[{"text": "Grundlage für Zeitplanung", "correct": true, "because": "Strukturieren Ablauf"}, {"text": "Team motivieren", "correct": false, "because": "Anderer Fokus"}, {"text": "Kosten reduzieren", "correct": false, "because": "Unabhängig davon"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Arbeitspakete ohne Zeitangabe definiert werden?', 2, '[{"text": "Nein", "correct": true, "because": "Zeitrahmen ist essenziell"}, {"text": "Ja", "correct": false, "because": "Planung wird unklar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt ein gut definiertes Arbeitspaket?', 3, '[{"text": "Test mit 10 Szenarien bis 20. Juni", "correct": true, "because": "Klar und konkret"}, {"text": "Irgendwas testen", "correct": false, "because": "Zu ungenau"}, {"text": "Team soll arbeiten", "correct": false, "because": "Nicht spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Definition von Arbeitspaketen nur für den Projektleiter relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Team braucht Zuordnung"}, {"text": "Ja", "correct": false, "because": "Projektweite Bedeutung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat ein Arbeitspaket?', 4, '[{"text": "Klares Ergebnis", "correct": true, "because": "Definiert Ziel"}, {"text": "Vage Beschreibung", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "Verantwortlicher", "correct": true, "because": "Weist Zuständigkeit"}, {"text": "Ressourcenbedarf", "correct": true, "because": "Plant Einsatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Arbeitspakete dokumentiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Nachvollziehbarkeit wichtig"}, {"text": "Nein", "correct": false, "because": "Dokumentation hilft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktion haben Arbeitspakete?', 3, '[{"text": "Projektsteuerung ermöglichen", "correct": true, "because": "Fördern Übersicht"}, {"text": "Zeit verlängern", "correct": false, "because": "Kein Ziel"}, {"text": "Technische Lösung finden", "correct": false, "because": "Anderer Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Arbeitspaket mehrere Aufgaben umfassen?', 2, '[{"text": "Ja", "correct": true, "because": "Wenn klar abgegrenzt"}, {"text": "Nein", "correct": false, "because": "Flexibilität erlaubt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor erschwert das Definieren von Arbeitspaketen?', 3, '[{"text": "Unklarer Projektumfang", "correct": true, "because": "Verhindert Struktur"}, {"text": "Klares Team", "correct": false, "because": "Fördert Definition"}, {"text": "Gute Planung", "correct": false, "because": "Unterstützt Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Arbeitspakete unterstützen die Ressourcenplanung. b) Sie sind nur für IT-Projekte nötig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, breit anwendbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nutzen des Definierens von Arbeitspaketen?', 3, '[{"text": "Bessere Kontrolle", "correct": true, "because": "Fördert Übersicht"}, {"text": "Maximale Unklarheit", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Keine Zuordnung", "correct": false, "because": "Gegenteil erreicht"}]');
